  values ((select id from public.lessons where slug = 'alternate-segment-theorem'), 1, 'video_check', 'PQ is a tangent to the circle at A. The angle between the tangent AQ and the chord AB is 58°. C is a point on the circle in the alternate segment. Find angle ACB, marked x.', 58, 0.01, '°', 'Which angle sits in the segment on the other side of chord AB?', 'The tangent AQ and the chord AB meet at A with an angle of 58°. By the alternate segment theorem, the angle in the alternate segment is equal to it. Angle ACB stands in that segment, so x = 58°.', 'assets/figures/segment-q1.svg');
insert into public.questions (lesson_id, position, kind, prompt, answer, tolerance, unit, hint, solution, figure)
  values ((select id from public.lessons where slug = 'alternate-segment-theorem'), 2, 'calculation', 'PQ is a tangent at A. Triangle ABC is inscribed in the circle with angle ACB = 41°. Find the angle y between the tangent AQ and the chord AB.', 41, 0.01, '°', 'The theorem works in both directions: the angle in the alternate segment tells you the tangent-chord angle.', 'Angle ACB is in the segment on the opposite side of chord AB from the tangent AQ, so it is the angle in the alternate segment. By the theorem it equals the tangent-chord angle. y = 41°.', 'assets/figures/segment-q2.svg');
insert into public.questions (lesson_id, position, kind, prompt, answer, tolerance, unit, hint, solution, figure)
  values ((select id from public.lessons where slug = 'alternate-segment-theorem'), 3, 'calculation', 'PQ is a tangent at A. Angle PAB = 65° and angle QAC = 47°. Find angle BAC, marked z.', 68, 0.01, '°', 'PAQ is a straight line. What do the three angles at A add up to?', 'PAQ is a straight line, so the angles at A add to 180°. z = 180° − 65° − 47° = 68°. Bonus: the theorem gives the other two angles for free. Angle ACB = angle PAB = 65° and angle ABC = angle QAC = 47°. Check: 68 + 65 + 47 = 180.', 'assets/figures/segment-q3.svg');
insert into public.questions (lesson_id, position, kind, prompt, answer, tolerance, unit, hint, solution, figure)
  values ((select id from public.lessons where slug = 'alternate-segment-theorem'), 4, 'calculation', 'PQ is a tangent at A. The angle between AQ and the chord AB is 52°, and angle ABC = 73°. Find angle BAC, marked w.', 55, 0.01, '°', 'First use the theorem to find angle ACB. Then use the angle sum of triangle ABC.', 'By the alternate segment theorem, angle ACB equals the angle between the tangent AQ and the chord AB, so angle ACB = 52°. In triangle ABC the angles add to 180°: w = 180° − 52° − 73° = 55°.', 'assets/figures/segment-q4.svg');
